void mrb_gc_mark_context_stack(mrb_state *mrb, struct mrb_context *c) {
  struct mrb_stack *stack = c->stack;
  mrb_value *sp = c->stack->sp;
  mrb_value *base = c->stack->base;
  mrb_value *top = c->stack->top;
  mrb_value *p;

  if (!stack) return;

  for (p = base; p < sp; p++) {
    mrb_gc_mark(mrb, *p);
  }

  for (; p < top; p++) {
    *p = mrb_nil_value();
  }
}

void mrb_gc_mark_context(mrb_state *mrb, struct mrb_context *c)
{
  mrb_value *stack;
  mrb_value *sp;
  int i;

  stack = c->stack;
  if (!stack) return;

  sp = c->sp;

  for (i = 0; i < (sp - stack); i++) {
    mrb_gc_mark(mrb, stack[i]);
  }

  while (sp < c->stack_end) {
    *sp++ = mrb_nil_value();
  }
}

void mrb_gc_mark_context_stack(mrb_state *mrb, struct mrb_context *c) {
  if (!c->stack) return;

  mrb_value *sp = c->stack + c->stack_size;
  mrb_value *base = c->stack + c->stack_start;
  mrb_value *ep = c->stack + c->stack_size;
  mrb_value *p;

  for (p = base; p < sp; p++) {
    if (!mrb_immediate_p(*p)) {
      mrb_gc_mark(mrb, *p);
    }
  }

  for (; p < ep; p++) {
    mrb_value v = mrb_nil_value();
    *p = v;
  }
}

void mrb_gc_mark_context_stack(mrb_state *mrb, struct mrb_context *c) {
  mrb_value *sp;

  if (c->stack == NULL) return;

  sp = c->stack;
  while (sp < c->stack + c->stack_size) {
    mrb_gc_mark(mrb, *sp);
    sp++;
  }

  sp = c->stack + c->stack_size;
  while (sp < c->stack + MRB_STACK_SIZE) {
    *sp++ = mrb_nil_value();
  }
}

